// gh-pr-summarize Action - Self-contained, no external deps
// Uses native node:https and fetch for GitHub API calls

const fs = require('fs');
const path = require('path');
const https = require('https');
const { URL } = require('url');

// Core output helpers
function setOutput(name, value) {
  const file = process.env.GITHUB_OUTPUT || path.join(process.env.GITHUB_WORKSPACE || '.', '.github-output');
  try {
    fs.appendFileSync(file, `${name}=${value}\n`, 'utf8');
  } catch (e) {
    process.env[`GITHUB_OUTPUT_${name}`] = value;
  }
}

function setFailed(message) {
  console.error(`::error::${message}`);
  process.exit(1);
}

function info(msg) {
  console.log(`::debug::${msg}`);
}

// HTTP request helper
function httpRequest(url, options = {}) {
  return new Promise((resolve, reject) => {
    const urlObj = new URL(url);
    const req = https.request(urlObj, {
      method: options.method || 'GET',
      headers: options.headers || {},
    }, (res) => {
      let data = '';
      res.on('data', (chunk) => data += chunk);
      res.on('end', () => {
        resolve({ status: res.status, headers: res.headers, body: data });
      });
    });
    req.on('error', reject);
    if (options.body) req.write(options.body);
    req.end();
  });
}

async function run() {
  try {
    const githubToken = process.env.INPUT_GITHUB_TOKEN || process.env.GITHUB_TOKEN || '';
    const openrouterApiKey = process.env.INPUT_OPENROUTER_API_KEY || process.env.OPENROUTER_API_KEY || '';
    const model = process.env.INPUT_MODEL || 'google/gemini-2.5-flash';
    const outputFormat = process.env.INPUT_OUTPUT_FORMAT || 'markdown';
    const autoComment = (process.env.INPUT_AUTO_COMMENT || 'true').toLowerCase() === 'true';

    // Get PR info from environment
    const repoFull = process.env.GITHUB_REPOSITORY || '';
    const [owner, repo] = repoFull.split('/');
    const ref = process.env.GITHUB_REF || '';
    const prMatch = ref.match(/pull\/(\d+)/);
    const prNumber = prMatch ? prMatch[1] : '';

    if (!prNumber) {
      setFailed('No PR number found. This action must run on pull_request events.');
      return;
    }

    info(`Summarizing PR #${prNumber} in ${owner}/${repo}`);

    // Get PR diff from GitHub API
    const prUrl = `https://api.github.com/repos/${owner}/${repo}/pulls/${prNumber}`;
    const prResp = await httpRequest(prUrl, {
      headers: {
        'Authorization': `Bearer ${githubToken}`,
        'Accept': 'application/vnd.github.v3.diff',
        'X-GitHub-Api-Version': '2022-11-28',
        'User-Agent': 'gh-pr-summarize-action',
      },
    });

    if (prResp.status !== 200) {
      setFailed(`Failed to fetch PR: ${prResp.status} ${prResp.body}`);
      return;
    }

    const diff = prResp.body;
    info(`Diff retrieved, length: ${diff.length} chars`);

    // Get PR metadata for additional context
    const prMetaResp = await httpRequest(prUrl, {
      headers: {
        'Authorization': `Bearer ${githubToken}`,
        'Accept': 'application/vnd.github.v3+json',
        'X-GitHub-Api-Version': '2022-11-28',
        'User-Agent': 'gh-pr-summarize-action',
      },
    });

    let prMeta = {};
    if (prMetaResp.status === 200) {
      prMeta = JSON.parse(prMetaResp.body);
    }

    // Summarize with AI or fall back to heuristic
    let summary = '';
    if (openrouterApiKey) {
      summary = await summarizeWithAI(diff, prMeta, model, openrouterApiKey);
    } else {
      summary = heuristicSummary(diff, prMeta);
    }

    // Output results
    if (outputFormat === 'json') {
      const jsonOutput = JSON.stringify({
        pr_number: parseInt(prNumber),
        repository: `${owner}/${repo}`,
        title: prMeta.title || '',
        author: prMeta.user?.login || '',
        summary,
        model: openrouterApiKey ? model : 'heuristic',
        diff_length: diff.length,
      });
      setOutput('summary', jsonOutput);
      fs.writeFileSync(path.join(process.env.GITHUB_WORKSPACE || '.', 'pr-summary.json'), jsonOutput);
    } else {
      setOutput('summary', summary);
      fs.writeFileSync(path.join(process.env.GITHUB_WORKSPACE || '.', 'pr-summary.md'), summary);
    }

    // Post comment on PR
    if (autoComment && summary) {
      const commentBody = `## Summary\n${summary}\n\n---\n*Generated by [gh-pr-summarize](https://github.com/${owner}/${repo}/actions)*`;
      await httpRequest(`https://api.github.com/repos/${owner}/${repo}/issues/${prNumber}/comments`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${githubToken}`,
          'Accept': 'application/vnd.github.v3+json',
          'X-GitHub-Api-Version': '2022-11-28',
          'User-Agent': 'gh-pr-summarize-action',
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ body: commentBody }),
      });
      info('Comment posted to PR');
    }

    info('Summary complete!');

  } catch (error) {
    setFailed(error.message);
  }
}

async function summarizeWithAI(diff, prMeta, model, apiKey) {
  const truncatedDiff = diff.substring(0, 8000);
  const title = prMeta.title || 'N/A';
  const author = prMeta.user?.login || 'N/A';
  const body = prMeta.body || '';

  const prompt = `You are a senior code reviewer. Analyze this PR diff and create a concise summary.

PR Title: ${title}
Author: ${author}
PR Description: ${body?.substring(0, 500) || 'N/A'}

Create a summary with these sections:
## Summary
2-3 sentences describing what this PR does.

## Key Changes
- List key changes (2-3 bullet points, file-level granularity)

## Impact
- Test coverage impact and deployment risk (low/medium/high)

## Risk Assessment
- Deployment risk with 1-sentence justification

Format as Markdown. Keep professional and actionable.

\`\`\`diff
${truncatedDiff}
\`\`\``;

  return new Promise((resolve) => {
    const body = JSON.stringify({
      model: model,
      messages: [{ role: 'user', content: prompt }],
      temperature: 0.3,
      max_tokens: 2000,
    });

    const req = https.request('https://openrouter.ai/api/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(body),
        'HTTP-Referer': 'https://github.com/13DJTEQ/gh-pr-summarize',
        'X-Title': 'GH PR Summarize Action',
      },
    }, (res) => {
      let data = '';
      res.on('data', (chunk) => data += chunk);
      res.on('end', () => {
        try {
          const json = JSON.parse(data);
          if (json.choices && json.choices[0]) {
            resolve(json.choices[0].message.content);
          } else if (json.error) {
            resolve(`AI Error: ${json.error.message}\n\n${fallbackSummary(diff, prMeta)}`);
          } else {
            resolve(fallbackSummary(diff, prMeta));
          }
        } catch (e) {
          resolve(fallbackSummary(diff, prMeta));
        }
      });
    });

    req.on('error', () => resolve(fallbackSummary(diff, prMeta)));
    req.write(body);
    req.end();
  });
}

function fallbackSummary(diff, prMeta) {
  const lines = diff.split('\n');
  const added = lines.filter(l => l.startsWith('+') && !l.startsWith('+++')).length;
  const removed = lines.filter(l => l.startsWith('-') && !l.startsWith('---')).length;
  const files = [...new Set(lines.filter(l => l.startsWith('diff --git')).map(l => {
    const match = l.match(/diff --git a\/(.+?) b\//);
    return match ? match[1] : '';
  }).filter(Boolean))];

  const totalChanges = added + removed;
  const risk = totalChanges > 500 ? 'high' : (totalChanges > 100 ? 'medium' : 'low');

  return `## Summary\n${prMeta.title || 'PR Summary'} (heuristic mode - add OPENROUTER_API_KEY for AI analysis)\n\n## Key Changes\n- ${added} lines added, ${removed} lines removed\n- Files modified: ${files.join(', ') || 'N/A'}\n\n## Impact\n- Deployment risk: **${risk}** based on ${totalChanges} lines changed\n\n## Risk Assessment\n- Risk: ${risk} — heuristic summary based on change volume only.\n`;
}

function heuristicSummary(diff, prMeta) {
  return fallbackSummary(diff, prMeta);
}

run();